// Acceptance tests for lane cob-c (plan Tasks 6–7). Written by the orchestrator before dispatch.
// They go through the package entry point '@cob/core', the way the app and the agent import it.
// Do not edit this file; add your own tests in the per-module test files.
import { beforeEach, expect, test } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {
  BUTTONS,
  CONFIRMED,
  DataRepo,
  UNSURE,
  UnsendablePointError,
  beginSubmit,
  createCommand,
  inboxRows,
  processQueue,
  queuedCommands,
  recordOutcome,
  upsertRole,
  type Point,
} from '@cob/core';

const T0 = '2026-11-11T09:00:00.000Z';
const T1 = '2026-11-11T10:00:00.000Z';

const point = (o: Partial<Point> = {}): Point => ({
  id: 'p1',
  kind: 'answer',
  label: 'Notice period',
  text: '30 days',
  rank: CONFIRMED,
  rev: 1,
  evidence: { type: 'said', quote: '30 days' },
  interviewId: 'i1',
  createdAt: T0,
  updatedAt: T0,
  ...o,
});
const job = { organization: 'Example Foods', title: 'Warehouse supervisor', link: 'https://careers.example.com/jobs/1' };

let dir: string;
let app: DataRepo;
let agent: DataRepo;

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'cob-acc-c-'));
  app = new DataRepo(dir, 'app');
  agent = new DataRepo(dir, 'agent');
  app.putSingleton('lanes', { lanes: [{ id: 'one-outreach', name: 'One outreach' }] });
});

const interrupted = (): string => {
  app.put('point', point());
  const s = beginSubmit(agent, job, { resumeFile: 'cv.pdf', points: [{ pointId: 'p1', rev: 1, field: 'Notice period' }] }, new Date(T0));
  processQueue(agent, new Date(T1));
  return s.id;
};

test('C1 (20.3) an unsure, stale or missing point is refused before the click and nothing is written', () => {
  expect(UnsendablePointError).toBeTypeOf('function');
  expect(beginSubmit).toBeTypeOf('function');
  app.put('point', point({ id: 'u', rank: UNSURE }));
  app.put('point', point({ id: 'p', rev: 2 }));
  expect(() => beginSubmit(agent, job, { resumeFile: 'cv.pdf', points: [{ pointId: 'u', rev: 1, field: 'Notice period' }] })).toThrow(UnsendablePointError);
  expect(() => beginSubmit(agent, job, { resumeFile: 'cv.pdf', points: [{ pointId: 'p', rev: 1 }] })).toThrow(UnsendablePointError);
  expect(() => beginSubmit(agent, job, { resumeFile: 'cv.pdf', points: [{ pointId: 'missing', rev: 1 }] })).toThrow(UnsendablePointError);
  expect(agent.list('application').items).toEqual([]);
});

test('C2 a normal submit records exactly what was sent, and a later correction does not rewrite it', () => {
  app.put('point', point());
  const refs = [{ pointId: 'p1', rev: 1, field: 'Notice period' }];
  const s = beginSubmit(agent, job, { resumeFile: 'cv.pdf', points: refs }, new Date(T0));
  expect(s).toMatchObject({ state: 'submitting', park: null, pendingSubmission: { resumeFile: 'cv.pdf', points: refs, startedAt: T0 } });
  const done = recordOutcome(agent, { applicationId: s.id }, { type: 'submitted', resumeFile: 'cv.pdf', points: refs }, new Date(T1));
  expect(done).toMatchObject({ state: 'submitted', pendingSubmission: null, submission: { resumeFile: 'cv.pdf', points: refs, submittedAt: T1 } });
  app.put('point', point({ rev: 2, text: '60 days' }));
  expect(agent.get('application', s.id)!.submission!.points).toEqual(refs);
  expect(inboxRows(agent)).toEqual([]);
});

test('C3 a run that stopped after the click becomes a may-have-been-sent row, never a silent retry', () => {
  app.put('point', point());
  const s = beginSubmit(agent, job, { resumeFile: 'cv.pdf', points: [{ pointId: 'p1', rev: 1 }] }, new Date(T0));
  expect(processQueue(agent, new Date(T1))).toEqual([]);
  expect(agent.get('application', s.id)).toMatchObject({
    state: 'parked',
    park: { type: 'error', afterSubmit: true },
    pendingSubmission: { startedAt: T0 },
  });
  expect(inboxRows(agent)[0]).toMatchObject({ applicationId: s.id, rowType: 'error_after_submit' });
  expect(BUTTONS.error_after_submit).toEqual(['done', 'status', 'retry', 'drop']);
});

test('C4 Done on a may-have-been-sent row records it as submitted at the click time', () => {
  const id = interrupted();
  createCommand(app, { verb: 'done', target: id, payload: {} });
  processQueue(agent);
  expect(agent.get('application', id)).toMatchObject({
    state: 'submitted',
    park: null,
    pendingSubmission: null,
    submission: { resumeFile: 'cv.pdf', points: [{ pointId: 'p1', rev: 1, field: 'Notice period' }], submittedAt: T0 },
  });
  expect(queuedCommands(app)).toEqual([]);
});

test('C5 Retry on a may-have-been-sent row needs notSent: true', () => {
  const id = interrupted();
  const c1 = createCommand(app, { verb: 'retry', target: id, payload: {} });
  expect(processQueue(agent)).toEqual([]);
  expect(agent.get('command', c1.id)).toMatchObject({ state: 'failed', resultNote: 'failed: confirm the application was not sent before retrying' });
  const c2 = createCommand(app, { verb: 'retry', target: id, payload: { notSent: true } });
  expect(processQueue(agent)).toEqual([{ type: 'retry', applicationId: id, commandId: c2.id }]);
});

test('C6 (20.20) an error before the click is an error row with the note, and retries without a question', () => {
  const a = recordOutcome(agent, job, { type: 'park', park: { type: 'error', note: 'Upload failed' } }, new Date(T0));
  expect(inboxRows(agent)[0]).toMatchObject({ rowType: 'error', note: 'Upload failed' });
  const c = createCommand(app, { verb: 'retry', target: a.id, payload: {} });
  expect(processQueue(agent)).toEqual([{ type: 'retry', applicationId: a.id, commandId: c.id }]);
});

test('C7 lane ticks stay queued for a later agent version', () => {
  createCommand(app, { verb: 'lane_done', target: 'one-outreach', payload: { day: '2026-11-11' } });
  expect(processQueue(agent)).toEqual([]);
  expect(queuedCommands(app).map((c) => c.verb)).toEqual(['lane_done']);
});

test('C8 status then drop apply in order; a queued drop shows as pending; closed rows leave the inbox', () => {
  const a = recordOutcome(agent, job, { type: 'park', park: { type: 'captcha' } }, new Date(T0));
  createCommand(app, { verb: 'status', target: a.id, payload: { kind: 'rejection', text: 'Not moving forward' } }, new Date(T0));
  createCommand(app, { verb: 'drop', target: a.id, payload: { reason: 'rejected' } }, new Date(T1));
  expect(inboxRows(agent)[0]!.pending).toBe('drop');
  expect(processQueue(agent)).toEqual([]);
  expect(agent.get('application', a.id)).toMatchObject({ state: 'dropped', statusNotes: [expect.objectContaining({ kind: 'rejection' })] });
  expect(inboxRows(agent)).toEqual([]);
});

test('C9 the same job link with tracking params is one role', () => {
  const role = { title: 'Picker', organization: 'Example Foods', sourceId: 's1', applyPath: 'form' as const };
  const a = upsertRole(agent, { ...role, link: 'https://careers.example.com/jobs/7' }, new Date(T0));
  const b = upsertRole(agent, { ...role, link: 'https://careers.example.com/jobs/7/?utm_source=x' }, new Date(T1));
  expect(b).toMatchObject({ isNew: false, role: { id: a.role.id, foundAt: T0 } });
  expect(agent.list('role').items).toHaveLength(1);
});

test('C10 code rows offer a paste box only while the agent waits; human rows carry the contact', () => {
  const code = recordOutcome(agent, job, { type: 'park', park: { type: 'code', site: 'jobs.example.com' } }, new Date(T0));
  const human = recordOutcome(
    agent,
    { ...job, link: 'https://careers.example.com/jobs/2' },
    { type: 'park', park: { type: 'human', contact: 'jobs@example.com' } },
    new Date(T0),
  );
  const rows = (live?: Set<string>) =>
    Object.fromEntries(inboxRows(agent, live ? { waitingCodes: live } : undefined).map((r) => [r.applicationId, r]));
  expect(rows()[code.id]).toMatchObject({ rowType: 'code_closed', buttons: ['run_now', 'status', 'retry', 'drop'] });
  expect(rows(new Set([code.id]))[code.id]).toMatchObject({ rowType: 'code_waiting', buttons: ['paste_code', 'status', 'retry', 'drop'] });
  expect(rows()[human.id]).toMatchObject({ rowType: 'human', contact: 'jobs@example.com', buttons: ['done', 'status', 'retry', 'drop'] });
});
